package blockbranch.realistic;
import java.util.*;
public final class TemperateOceanCheck {
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);int ocean=0,retained=0,deepCandidate=0,retainedDeep=0;for(int z=-1900000;z<=1900000;z+=16000)for(int x=-1900000;x<=1900000;x+=16000){if(MarineShelf.contains(x,z,d)){if(TemperateOcean.contains(seed,x,z,d,c))ocean++;else retained++;}if(DeepOcean.contains(x,z,d)){if(TemperateOcean.deepCandidate(x,z,d,c))deepCandidate++;else retainedDeep++;}}
 require(ocean>100&&retained>100&&deepCandidate>1000&&retainedDeep>1000,"Substantial thermal partition, not wholesale specific-habitat relabel");pattern(seed);var p=blockbranch.realistic.TemperateOceanFixtures.fixture(d,seed);int kelp=0,gaps=0;var heights=new HashSet<Integer>();for(int z=p.z()-64;z<p.z()+64;z++)for(int x=p.x()-64;x<p.x()+64;x++){int h=TemperateOcean.kelpHeight(seed,x,z,d,c);if(h==0){gaps++;continue;}kelp++;heights.add(h);var s=MarineShelf.site(d,x,z);require(s.depth()>=4&&s.depth()<=10&&h<s.depth()&&s.slope()<=.18&&TemperateOcean.cover(seed,x,z,d,c)==9,"Hard supported substrate and conservative photic depth");}require(kelp>20&&gaps>kelp&&heights.size()>=3,"Sparse variable-height colonies and open gaps");var columns=new LinkedHashMap<String,int[]>();for(int z=(p.z()>>4)-2;z<=(p.z()>>4)+2;z++)for(int x=(p.x()>>4)-2;x<=(p.x()>>4)+2;x++){var a=TemperateOcean.column(seed,x,z,d,c);require(a.length<2048,"Bounded packed vegetation");columns.put(x+","+z,a);}var keys=new ArrayList<>(columns.keySet());Collections.reverse(keys);for(var key:keys){var q=key.split(",");require(Arrays.equals(columns.get(key),TemperateOcean.column(seed,Integer.parseInt(q[0]),Integer.parseInt(q[1]),d,c)),"Negative-coordinate and chunk-order consistency");}
 System.out.println("TEMPERATE_OCEAN seed="+seed+" point="+p+" ocean="+ocean+" retainedShelf="+retained+" deepCandidates="+deepCandidate+" retainedBasin="+retainedDeep+" kelp="+kelp+" gaps="+gaps+" heights="+heights);}
 System.out.println("TEMPERATE_OCEAN_THERMAL_PARTITION_LIGHT_SUBSTRATE_COLONIES_ORDER_PASS");}
 static double phaseCV(int[]x,int[]z,int total){double mean=total/16.0,v=0;for(int i=0;i<16;i++)v+=Math.pow(x[i]-mean,2)+Math.pow(z[i]-mean,2);return Math.sqrt(v/32)/mean;}
 static void pattern(long seed){int[] phaseX=new int[16],phaseZ=new int[16],gridX=new int[16],gridZ=new int[16];int total=0,pairs=0,gridTotal=0;for(int z=-256;z<256;z++)for(int x=-256;x<256;x++){if(Math.floorMod(x,4)==0&&Math.floorMod(z,4)==0){gridTotal++;gridX[Math.floorMod(x,16)]++;gridZ[Math.floorMod(z,16)]++;}if(TemperateOcean.colony(seed,x,z)){total++;phaseX[Math.floorMod(x,16)]++;phaseZ[Math.floorMod(z,16)]++;if(TemperateOcean.colony(seed,x+1,z))pairs++;}}double cv=phaseCV(phaseX,phaseZ,total),negative=phaseCV(gridX,gridZ,gridTotal),density=total/(512.0*512),near=pairs/(double)total;require(cv<.15&&near>density*1.5,"Colony clustering without coordinate-phase rows");require(negative>1,"The same phase diagnostic rejects a regular four-block planting lattice");System.out.println("OCEAN_KELP_PATTERN seed="+seed+" phaseCV="+cv+" latticeNegativeCV="+negative+" density="+density+" neighbour="+near);}
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
